import assert from 'node:assert/strict';
import { callTool, listTools } from './server.mjs';

// Basic creation
test('creates ticket with default priority', async () => {
  const r = await callTool('ticket_create', { title: 'Bug', description: 'Broken' });
  assert.match(r.content[0].text, /t\d/);
  assert.match(r.content[0].text, /normal/);
});

// Sequential IDs
test('generates sequential ticket ids', async () => {
  const r1 = await callTool('ticket_create', { title: 'A', description: 'A desc' });
  const r2 = await callTool('ticket_create', { title: 'B', description: 'B desc' });
  assert.match(r1.content[0].text, /t\d+/);
  assert.match(r2.content[0].text, /t\d+/);
  const id1 = r1.content[0].text.match(/t(\d+)/)[1];
  const id2 = r2.content[0].text.match(/t(\d+)/)[1];
  assert.equal(Number(id2), Number(id1) + 1);
});

// Explicit priorities
test('accepts explicit priority low', async () => {
  const r = await callTool('ticket_create', { title: 'X', description: 'Y', priority: 'low' });
  assert.match(r.content[0].text, /low/);
});

test('accepts explicit priority high', async () => {
  const r = await callTool('ticket_create', { title: 'X', description: 'Y', priority: 'high' });
  assert.match(r.content[0].text, /high/);
});

test('accepts explicit priority normal', async () => {
  const r = await callTool('ticket_create', { title: 'X', description: 'Y', priority: 'normal' });
  assert.match(r.content[0].text, /normal/);
});

// Invalid: missing title
test('rejects missing title', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { description: 'D' }),
    /title/
  );
});

// Invalid: empty title
test('rejects empty title', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: '', description: 'D' }),
    /title/
  );
});

test('rejects whitespace-only title', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: '   ', description: 'D' }),
    /title/
  );
});

// Invalid: missing description
test('rejects missing description', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: 'T' }),
    /description/
  );
});

// Invalid: empty description
test('rejects empty description', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: 'T', description: '' }),
    /description/
  );
});

// Invalid: bad priority
test('rejects invalid priority', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: 'T', description: 'D', priority: 'urgent' }),
    /priority/
  );
});

// Invalid: unknown tool
test('rejects unknown tool', async () => {
  await assert.rejects(
    () => callTool('unknown_tool', {}),
    /Unknown tool/
  );
});

// Invalid: extra fields rejected
test('rejects extra fields', async () => {
  await assert.rejects(
    () => callTool('ticket_create', { title: 'T', description: 'D', extra: 'nope' }),
    /extra/
  );
});

// Content type is text
test('returns text content type', async () => {
  const r = await callTool('ticket_create', { title: 'T', description: 'D' });
  assert.equal(r.content[0].type, 'text');
  assert.ok(typeof r.content[0].text === 'string');
});

// listTools returns the tool definition
test('listTools includes ticket_create', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  assert.equal(tools[0].name, 'ticket_create');
  assert.ok(tools[0].inputSchema);
  assert.deepEqual(tools[0].inputSchema.required, ['title', 'description']);
  assert.ok(tools[0].inputSchema.additionalProperties === false);
});
"}

