let nextId = 1;
const VALID_PRIORITIES = new Set(['low', 'normal', 'high']);

const toolDef = {
  name: 'ticket_create',
  description: 'Create a support ticket with title, description, and optional priority.',
  inputSchema: {
    type: 'object',
    properties: {
      title: { type: 'string', description: 'Ticket title (required, non-empty)' },
      description: { type: 'string', description: 'Ticket description (required, non-empty)' },
      priority: { type: 'string', enum: ['low', 'normal', 'high'], description: 'Priority level (default: normal)' },
    },
    required: ['title', 'description'],
    additionalProperties: false,
  },
};

const TOOLS = [toolDef];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Reject extra fields
  const allowed = new Set(['title', 'description', 'priority']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  // Validate required fields
  if (typeof args.title !== 'string' || args.title.trim() === '') {
    throw new Error('title is required and must be a non-empty string');
  }
  if (typeof args.description !== 'string' || args.description.trim() === '') {
    throw new Error('description is required and must be a non-empty string');
  }

  // Default and validate priority
  const priority = args.priority ?? 'normal';
  if (!VALID_PRIORITIES.has(priority)) {
    throw new Error(`priority must be one of: low, normal, high`);
  }

  const id = `t${nextId++}`;

  return {
    content: [
      {
        type: 'text',
        text: `Ticket ${id} created: "${args.title.trim()}" (${priority})`,
      },
    ],
  };
}
